-- PixelForge Games - estructura de la base de datos para Oracle 19c
-- Contiene las 9 tablas funcionales del proyecto y sus relaciones.
-- La instalación normal de la aplicación se realiza con las migraciones de Django.
-- Este archivo puede revisarse o ejecutarse por separado en un esquema vacío;
-- después se pueden cargar los datos con database/seed.sql.

WHENEVER SQLERROR EXIT SQL.SQLCODE
SET DEFINE OFF

CREATE TABLE "PF_ROLES" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "CODIGO" NVARCHAR2(20),
    "NOMBRE" NVARCHAR2(50),
    "DESCRIPCION" NVARCHAR2(200),
    CONSTRAINT "PF_ROLES_PK" PRIMARY KEY ("ID"),
    CONSTRAINT "PF_ROLES_CODIGO_UK" UNIQUE ("CODIGO")
);

CREATE TABLE "PF_CATEGORIAS" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NOMBRE" NVARCHAR2(60),
    "SLUG" NVARCHAR2(70),
    "DESCRIPCION" NVARCHAR2(250),
    "IMAGEN" NVARCHAR2(200),
    "ACTIVA" NUMBER(1) NOT NULL,
    CONSTRAINT "PF_CATEGORIAS_PK" PRIMARY KEY ("ID"),
    CONSTRAINT "PF_CATEGORIAS_NOMBRE_UK" UNIQUE ("NOMBRE"),
    CONSTRAINT "PF_CATEGORIAS_SLUG_UK" UNIQUE ("SLUG"),
    CONSTRAINT "PF_CATEGORIAS_ACTIVA_CK" CHECK ("ACTIVA" IN (0, 1))
);

CREATE TABLE "PF_USUARIOS" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "PASSWORD" NVARCHAR2(128),
    "LAST_LOGIN" TIMESTAMP NULL,
    "IS_SUPERUSER" NUMBER(1) NOT NULL,
    "USERNAME" NVARCHAR2(150),
    "FIRST_NAME" NVARCHAR2(150),
    "LAST_NAME" NVARCHAR2(150),
    "IS_STAFF" NUMBER(1) NOT NULL,
    "IS_ACTIVE" NUMBER(1) NOT NULL,
    "DATE_JOINED" TIMESTAMP NOT NULL,
    "EMAIL" NVARCHAR2(254),
    "NOMBRE_COMPLETO" NVARCHAR2(150),
    "FECHA_NACIMIENTO" DATE NULL,
    "DIRECCION" NVARCHAR2(250),
    "ROL_ID" NUMBER(19) NULL,
    CONSTRAINT "PF_USUARIOS_PK" PRIMARY KEY ("ID"),
    CONSTRAINT "PF_USUARIOS_USERNAME_UK" UNIQUE ("USERNAME"),
    CONSTRAINT "PF_USUARIOS_EMAIL_UK" UNIQUE ("EMAIL"),
    CONSTRAINT "PF_USUARIOS_SUPERUSER_CK" CHECK ("IS_SUPERUSER" IN (0, 1)),
    CONSTRAINT "PF_USUARIOS_STAFF_CK" CHECK ("IS_STAFF" IN (0, 1)),
    CONSTRAINT "PF_USUARIOS_ACTIVE_CK" CHECK ("IS_ACTIVE" IN (0, 1)),
    CONSTRAINT "PF_USUARIOS_ROL_FK" FOREIGN KEY ("ROL_ID")
        REFERENCES "PF_ROLES" ("ID") DEFERRABLE INITIALLY DEFERRED
);

CREATE INDEX "PF_USUARIOS_ROL_IX" ON "PF_USUARIOS" ("ROL_ID");

CREATE TABLE "PF_PRODUCTOS" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NOMBRE" NVARCHAR2(150),
    "DESCRIPCION" NCLOB,
    "PRECIO" NUMBER(10,2) NOT NULL,
    "IMAGEN" NVARCHAR2(200),
    "ACTIVO" NUMBER(1) NOT NULL,
    "CREADO" TIMESTAMP NOT NULL,
    "ACTUALIZADO" TIMESTAMP NOT NULL,
    "CATEGORIA_ID" NUMBER(19) NOT NULL,
    CONSTRAINT "PF_PRODUCTOS_PK" PRIMARY KEY ("ID"),
    CONSTRAINT "PF_PRODUCTOS_NOMBRE_UK" UNIQUE ("NOMBRE"),
    CONSTRAINT "PF_PRODUCTOS_ACTIVO_CK" CHECK ("ACTIVO" IN (0, 1)),
    CONSTRAINT "PF_PRODUCTOS_CATEGORIA_FK" FOREIGN KEY ("CATEGORIA_ID")
        REFERENCES "PF_CATEGORIAS" ("ID") DEFERRABLE INITIALLY DEFERRED
);

CREATE INDEX "PF_PRODUCTOS_CATEGORIA_IX" ON "PF_PRODUCTOS" ("CATEGORIA_ID");

CREATE TABLE "PF_INVENTARIO" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "STOCK" NUMBER(11) NOT NULL,
    "ACTUALIZADO" TIMESTAMP NOT NULL,
    "PRODUCTO_ID" NUMBER(19) NOT NULL,
    CONSTRAINT "PF_INVENTARIO_PK" PRIMARY KEY ("ID"),
    CONSTRAINT "PF_INVENTARIO_PRODUCTO_UK" UNIQUE ("PRODUCTO_ID"),
    CONSTRAINT "PF_INVENTARIO_STOCK_CK" CHECK ("STOCK" >= 0),
    CONSTRAINT "PF_INVENTARIO_PRODUCTO_FK" FOREIGN KEY ("PRODUCTO_ID")
        REFERENCES "PF_PRODUCTOS" ("ID") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "PF_CARRITOS" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ACTUALIZADO" TIMESTAMP NOT NULL,
    "USUARIO_ID" NUMBER(19) NOT NULL,
    CONSTRAINT "PF_CARRITOS_PK" PRIMARY KEY ("ID"),
    CONSTRAINT "PF_CARRITOS_USUARIO_UK" UNIQUE ("USUARIO_ID"),
    CONSTRAINT "PF_CARRITOS_USUARIO_FK" FOREIGN KEY ("USUARIO_ID")
        REFERENCES "PF_USUARIOS" ("ID") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "PF_ITEMS_CARRITO" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "CANTIDAD" NUMBER(11) NOT NULL,
    "CARRITO_ID" NUMBER(19) NOT NULL,
    "PRODUCTO_ID" NUMBER(19) NOT NULL,
    CONSTRAINT "PF_ITEMS_CARRITO_PK" PRIMARY KEY ("ID"),
    CONSTRAINT "PF_UQ_CARRITO_PRODUCTO" UNIQUE ("CARRITO_ID", "PRODUCTO_ID"),
    CONSTRAINT "PF_ITEMS_CARRITO_CANTIDAD_CK" CHECK ("CANTIDAD" >= 1),
    CONSTRAINT "PF_ITEMS_CARRITO_CARRITO_FK" FOREIGN KEY ("CARRITO_ID")
        REFERENCES "PF_CARRITOS" ("ID") DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "PF_ITEMS_CARRITO_PRODUCTO_FK" FOREIGN KEY ("PRODUCTO_ID")
        REFERENCES "PF_PRODUCTOS" ("ID") DEFERRABLE INITIALLY DEFERRED
);

CREATE INDEX "PF_ITEMS_CARRITO_CARRITO_IX" ON "PF_ITEMS_CARRITO" ("CARRITO_ID");
CREATE INDEX "PF_ITEMS_CARRITO_PRODUCTO_IX" ON "PF_ITEMS_CARRITO" ("PRODUCTO_ID");

CREATE TABLE "PF_PEDIDOS" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "FECHA" TIMESTAMP NOT NULL,
    "ESTADO" NVARCHAR2(15),
    "TOTAL" NUMBER(12,2) NOT NULL,
    "DIRECCION_DESPACHO" NVARCHAR2(250),
    "ULTIMOS_DIGITOS" NVARCHAR2(4),
    "USUARIO_ID" NUMBER(19) NOT NULL,
    CONSTRAINT "PF_PEDIDOS_PK" PRIMARY KEY ("ID"),
    CONSTRAINT "PF_PEDIDOS_USUARIO_FK" FOREIGN KEY ("USUARIO_ID")
        REFERENCES "PF_USUARIOS" ("ID") DEFERRABLE INITIALLY DEFERRED
);

CREATE INDEX "PF_PEDIDOS_USUARIO_IX" ON "PF_PEDIDOS" ("USUARIO_ID");

CREATE TABLE "PF_DETALLES_PEDIDO" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NOMBRE_PRODUCTO" NVARCHAR2(150),
    "PRECIO_UNITARIO" NUMBER(10,2) NOT NULL,
    "CANTIDAD" NUMBER(11) NOT NULL,
    "PEDIDO_ID" NUMBER(19) NOT NULL,
    "PRODUCTO_ID" NUMBER(19) NULL,
    CONSTRAINT "PF_DETALLES_PEDIDO_PK" PRIMARY KEY ("ID"),
    CONSTRAINT "PF_UQ_PEDIDO_PRODUCTO" UNIQUE ("PEDIDO_ID", "PRODUCTO_ID"),
    CONSTRAINT "PF_DETALLE_CANTIDAD_CK" CHECK ("CANTIDAD" >= 1),
    CONSTRAINT "PF_DETALLE_PEDIDO_FK" FOREIGN KEY ("PEDIDO_ID")
        REFERENCES "PF_PEDIDOS" ("ID") DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT "PF_DETALLE_PRODUCTO_FK" FOREIGN KEY ("PRODUCTO_ID")
        REFERENCES "PF_PRODUCTOS" ("ID") DEFERRABLE INITIALLY DEFERRED
);

CREATE INDEX "PF_DETALLE_PEDIDO_IX" ON "PF_DETALLES_PEDIDO" ("PEDIDO_ID");
CREATE INDEX "PF_DETALLE_PRODUCTO_IX" ON "PF_DETALLES_PEDIDO" ("PRODUCTO_ID");

COMMIT;
PROMPT Estructura de PixelForge Games creada correctamente.
